groupedBar.code:
// available: container (a <div>), data, params, d3, containerWidth
// Grouped bar chart: one group per scenario key, one bar per metric column -
// this uses every column at once, which none of the built-in bar/pie/table
// charts can do (they're locked to a single x/y field). Uses containerWidth
// so it redraws responsively when the node is resized.
container.innerHTML = "";

const keys = Object.keys(data);
const metrics = Object.keys(data[keys[0]] ?? {});

const margin = { top: 30, right: 20, bottom: 40, left: 60 };
const width = containerWidth - margin.left - margin.right;
const height = 260 - margin.top - margin.bottom;

const svg = d3.select(container)
  .append("svg")
  .attr("width", width + margin.left + margin.right)
  .attr("height", height + margin.top + margin.bottom)
  .append("g")
  .attr("transform", "translate(" + margin.left + "," + margin.top + ")");

const x0 = d3.scaleBand().domain(keys).range([0, width]).padding(0.25);
const x1 = d3.scaleBand().domain(metrics).range([0, x0.bandwidth()]).padding(0.1);
const y = d3.scaleLinear()
  .domain([0, d3.max(keys, (k) => d3.max(metrics, (m) => data[k][m]))])
  .nice()
  .range([height, 0]);
const color = d3.scaleOrdinal().domain(metrics).range(d3.schemeTableau10);

svg.append("g")
  .selectAll("g")
  .data(keys)
  .enter()
  .append("g")
  .attr("transform", (k) => "translate(" + x0(k) + ",0)")
  .selectAll("rect")
  .data((k) => metrics.map((m) => ({ metric: m, value: data[k][m] })))
  .enter()
  .append("rect")
  .attr("x", (d) => x1(d.metric))
  .attr("y", (d) => y(d.value))
  .attr("width", x1.bandwidth())
  .attr("height", (d) => height - y(d.value))
  .attr("fill", (d) => color(d.metric))
  .attr("rx", 3);

svg.append("g").attr("transform", "translate(0," + height + ")").call(d3.axisBottom(x0));
svg.append("g").call(d3.axisLeft(y).ticks(4));

// legend
const legend = svg.append("g").attr("transform", "translate(0, -20)");
metrics.forEach((m, i) => {
  const g = legend.append("g").attr("transform", "translate(" + i * 140 + ", 0)");
  g.append("rect").attr("width", 10).attr("height", 10).attr("fill", color(m));
  g.append("text").attr("x", 14).attr("y", 9).style("font-size", "10px").text(m);
});

bar.code:
const axis = params.axis === "x" ? "x" : "y";
const axisLabel = params.axisLabel ?? "";
const props = params;

const values = Object.fromEntries(
  Object.entries(data).map(([k, row]) => [k, row[axisLabel]]),
);

const width = containerWidth || 400;
const height = 220;
const entries = Object.entries(values);
const isHorizontal = axis === "x";
const colorProp = props?.color ?? props?.colors;
const barColors = entries.map(([label], index) => {
  if (typeof colorProp === "string") {
    return colorProp;
  }

  if (Array.isArray(colorProp) && colorProp.length > 0) {
    return colorProp[index % colorProp.length];
  }

  if (colorProp && typeof colorProp === "object" && !Array.isArray(colorProp)) {
    return colorProp[label] ?? d3.schemeTableau10[index % d3.schemeTableau10.length];
  }

  return d3.schemeTableau10[index % d3.schemeTableau10.length];
});

const margin = isHorizontal
  ? { top: 20, right: 10, bottom: 50, left: 90 }
  : { top: 20, right: 0, bottom: 50, left: 80 };
const innerWidth = width - margin.left - margin.right;
const innerHeight = height - margin.top - margin.bottom;

const svg = d3.select(container).append("svg").attr("width", width).attr("height", height);

const g = svg
  .append("g")
  .attr("transform", `translate(${margin.left},${margin.top})`);

if (isHorizontal) {
  const x = d3
    .scaleLinear()
    .domain([0, d3.max(entries, ([, v]) => v) ?? 0])
    .nice()
    .range([0, innerWidth]);

  const y = d3
    .scaleBand()
    .domain(entries.map(([k]) => k))
    .range([0, innerHeight])
    .padding(0.35);

  g.selectAll("rect")
    .data(entries)
    .enter()
    .append("rect")
    .attr("x", 0)
    .attr("y", ([k]) => y(k) ?? 0)
    .attr("width", ([, v]) => x(v))
    .attr("height", y.bandwidth())
    .attr("fill", (_d, i) => barColors[i])
    .attr("rx", 4)
    .attr("ry", 4);

  g.append("g")
    .attr("transform", `translate(0,${innerHeight})`)
    .call(d3.axisBottom(x).ticks(3))
    .selectAll("text")
    .style("font-size", "15px")
    .style("font-family", "Inter, sans-serif");

  g.append("g")
    .call(d3.axisLeft(y))
    .selectAll("text")
    .style("font-size", "15px")
    .style("font-family", "Inter, sans-serif");

  svg
    .append("text")
    .attr("x", width / 2 + 30)
    .attr("y", height - 10)
    .attr("text-anchor", "middle")
    .style("font-size", "16px")
    .style("font-family", "Inter, sans-serif")
    .text(props?.labelX ?? `${axisLabel} ${props?.unit ?? ""}`.trim());

  g.append("text")
    .attr("transform", "rotate(-90)")
    .attr("y", -70)
    .attr("x", -height / 2.5)
    .attr("text-anchor", "middle")
    .style("font-size", "15px")
    .style("font-family", "Inter, sans-serif")
    .text("Scenario");

  return;
}

const x = d3
  .scaleBand()
  .domain(entries.map(([k]) => k))
  .range([0, innerWidth])
  .padding(0.35);

const y = d3
  .scaleLinear()
  .domain([0, d3.max(entries, ([, v]) => v) ?? 0])
  .nice()
  .range([innerHeight, 0]);

g.selectAll("rect")
  .data(entries)
  .enter()
  .append("rect")
  .attr("x", ([k]) => x(k) ?? 0)
  .attr("y", ([, v]) => y(v))
  .attr("width", x.bandwidth())
  .attr("height", ([, v]) => innerHeight - y(v))
  .attr("fill", (_d, i) => barColors[i])
  .attr("rx", 4)
  .attr("ry", 4);

g.append("g")
  .attr("transform", `translate(0,${innerHeight})`)
  .call(d3.axisBottom(x))
  .selectAll("text")
  .style("font-size", "15px")
  .style("font-family", "Inter, sans-serif");

svg
  .append("text")
  .attr("x", width / 2 + 30)
  .attr("y", height - 10)
  .attr("text-anchor", "middle")
  .style("font-size", "16px")
  .style("font-family", "Inter, sans-serif")
  .text("Scenario");

g.append("g")
  .call(d3.axisLeft(y).ticks(3))
  .selectAll("text")
  .style("font-size", "15px")
  .style("font-family", "Inter, sans-serif");

g.append("text")
  .attr("transform", "rotate(-90)")
  .attr("y", -60)
  .attr("x", -height / 2.5)
  .attr("text-anchor", "middle")
  .style("font-size", "15px")
  .style("font-family", "Inter, sans-serif")
  .text(props?.labelY ?? `${axisLabel} ${props?.unit ?? ""}`.trim());

pie.code:
const axisLabel = params.axisLabel ?? "";
const props = params;

const values = Object.fromEntries(
  Object.entries(data).map(([k, row]) => [k, row[axisLabel]]),
);

const width = containerWidth || 260;
const height = 220;

const entries = Object.entries(values);
const colorProp = props?.color ?? props?.colors;
const entryColors = entries.map(([label], index) => {
  if (typeof colorProp === "string") {
    return colorProp;
  }

  if (Array.isArray(colorProp) && colorProp.length > 0) {
    return colorProp[index % colorProp.length];
  }

  if (colorProp && typeof colorProp === "object" && !Array.isArray(colorProp)) {
    return colorProp[label] ?? d3.schemeTableau10[index % d3.schemeTableau10.length];
  }

  return d3.schemeTableau10[index % d3.schemeTableau10.length];
});

const root = d3
  .select(container)
  .style("width", "100%")
  .style("overflow", "hidden")
  .style("display", "flex")
  .style("flex-direction", "column")
  .style("gap", "6px");

const legendRow = root
  .append("div")
  .style("display", "flex")
  .style("justify-content", "center")
  .style("align-items", "center")
  .style("gap", "16px")
  .style("padding", "0 6px")
  .style("flex-wrap", "wrap");

legendRow
  .append("div")
  .style("font-size", "16px")
  .style("font-family", "Inter, sans-serif")
  .style("font-weight", "500")
  .text("Scenario");

const legendItems = legendRow
  .append("div")
  .style("display", "flex")
  .style("gap", "14px")
  .style("flex-wrap", "wrap")
  .style("align-items", "center")
  .style("font-family", "Inter, sans-serif")
  .style("font-size", "16px")
  .style("font-weight", "500");

entries.forEach(([label], index) => {
  const item = legendItems
    .append("div")
    .style("display", "flex")
    .style("align-items", "center")
    .style("gap", "6px");
  item
    .append("span")
    .style("width", "14px")
    .style("height", "14px")
    .style("border-radius", "2px")
    .style("background-color", entryColors[index]);
  item.append("span").text(label);
});

const svg = root
  .append("svg")
  .style("display", "block")
  .style("margin", "0 auto")
  .attr("width", width)
  .attr("height", height);

root
  .append("div")
  .style("margin-top", "4px")
  .style("text-align", "center")
  .style("font-size", "16px")
  .style("font-family", "Inter, sans-serif")
  .style("font-weight", "500")
  .text(`${axisLabel} (${props?.unit ?? ""})`);

if (entries.length === 0) return;

const margin = 10;
const innerWidth = width - margin * 2;
const innerHeight = height - margin * 2;

const radius = Math.min(innerWidth, innerHeight) / 2;

const g = svg
  .append("g")
  .attr("transform", `translate(${width / 2}, ${height / 2 + 6})`);

const pie = d3
  .pie()
  .value(([, v]) => v)
  .sort(null);

const arc = d3
  .arc()
  .innerRadius(radius * 0.45)
  .outerRadius(radius);

const arcs = pie(entries);

g.selectAll("path")
  .data(arcs)
  .enter()
  .append("path")
  .attr("d", arc)
  .attr("fill", (_d, i) => entryColors[i])
  .attr("stroke", "#fff")
  .attr("stroke-width", 1.2);

g.selectAll("text.slice-label")
  .data(arcs)
  .enter()
  .append("text")
  .attr("class", "slice-label")
  .attr("transform", (d) => `translate(${arc.centroid(d)})`)
  .attr("text-anchor", "middle")
  .style("font-family", "Inter, sans-serif")
  .style("font-size", "15px")
  .style("fill", "#ffffff")
  .text((d) => d.data[1].toFixed(2));

table.code:
const axisLabel = params.axisLabel ?? "";
const props = params;

const values = Object.fromEntries(
  Object.entries(data).map(([k, row]) => [k, row[axisLabel]]),
);
const entries = Object.entries(values);

const label = props?.unit ? `${axisLabel} (${props.unit})` : axisLabel;

const wrapper = d3
  .select(container)
  .style("width", "100%")
  .style("overflow-x", "auto")
  .style("font-family", "Inter, sans-serif");

const table = wrapper
  .append("table")
  .style("width", "100%")
  .style("border-collapse", "separate")
  .style("border-spacing", "0")
  .style("font-size", "15px")
  .style("border-radius", "8px")
  .style("overflow", "hidden")
  .style("text-align", "center")
  .style("box-shadow", "0 1px 4px rgba(0,0,0,0.1)");

const headRow = table
  .append("thead")
  .append("tr")
  .style("background-color", "#f0f0f0");

headRow
  .append("th")
  .style("padding", "10px 12px")
  .style("border-bottom", "1px solid #e0e0e0")
  .style("font-weight", "600")
  .style("text-align", "center")
  .text("Scenario");

headRow
  .append("th")
  .style("padding", "10px 12px")
  .style("border-bottom", "1px solid #e0e0e0")
  .style("font-weight", "600")
  .style("text-align", "center")
  .text(label);

const tbody = table.append("tbody");

entries.forEach(([key, value], i) => {
  const row = tbody
    .append("tr")
    .style("background", i % 2 === 0 ? "white" : "#fafafa");

  row
    .append("td")
    .style("padding", "10px 12px")
    .style("border-bottom", "1px solid #f0f0f0")
    .text(key);

  row
    .append("td")
    .style("padding", "10px 12px")
    .style("border-bottom", "1px solid #f0f0f0")
    .style("font-variant-numeric", "tabular-nums")
    .style("font-weight", "500")
    .text(value.toFixed(5));
});

lollipop.code:
container.innerHTML = "";

const axisLabel = params.axisLabel ?? "";
const keys = Object.keys(data);
const margin = { top: 20, right: 20, bottom: 30, left: 20 };
const width = (containerWidth || 400) - margin.left - margin.right;
const height = keys.length * 40;

const svg = d3.select(container)
  .append("svg")
  .attr("width", width + margin.left + margin.right)
  .attr("height", height + margin.top + margin.bottom)
  .append("g")
  .attr("transform", "translate(" + margin.left + "," + margin.top + ")");

const x = d3.scaleLinear().domain([0, d3.max(keys, (k) => data[k][axisLabel])]).nice().range([0, width]);
const y = d3.scaleBand().domain(keys).range([0, height]).padding(0.4);

svg.selectAll("line")
  .data(keys)
  .enter()
  .append("line")
  .attr("x1", x(0))
  .attr("x2", (k) => x(data[k][axisLabel]))
  .attr("y1", (k) => y(k) + y.bandwidth() / 2)
  .attr("y2", (k) => y(k) + y.bandwidth() / 2)
  .attr("stroke", "#94a3b8")
  .attr("stroke-width", 2);

svg.selectAll("circle")
  .data(keys)
  .enter()
  .append("circle")
  .attr("cx", (k) => x(data[k][axisLabel]))
  .attr("cy", (k) => y(k) + y.bandwidth() / 2)
  .attr("r", 6)
  .attr("fill", "#2563eb");

svg.append("g").call(d3.axisLeft(y));
svg.append("g").attr("transform", "translate(0," + height + ")").call(d3.axisBottom(x).ticks(4));

GroupedBarVega.code:
{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "Grouped bar chart - one group per scenario key, one bar per metric field. data.values is auto-populated as {key, field, value} records.",
  "mark": "bar",
  "encoding": {
    "x": {
      "field": "key",
      "type": "nominal",
      "title": "Scenario"
    },
    "xOffset": {
      "field": "field"
    },
    "y": {
      "field": "value",
      "type": "quantitative"
    },
    "color": {
      "field": "field",
      "type": "nominal",
      "title": "Metric"
    }
  }
}
